  builder_.add_KP_CLOCK_ANGLES_DEG(KP_CLOCK_ANGLES_DEG);
  builder_.add_KP_PREDICTED(KP_PREDICTED);
  builder_.add_ARRIVAL_TIME(ARRIVAL_TIME);
  builder_.add_ISSUED_AT(ISSUED_AT);
  builder_.add_SOURCE_EVENT_ID(SOURCE_EVENT_ID);
  builder_.add_MODEL(MODEL);
  builder_.add_TARGET(TARGET);
  builder_.add_HAS_GLANCING_BLOW(HAS_GLANCING_BLOW);
  builder_.add_GLANCING_BLOW(GLANCING_BLOW);
  builder_.add_KIND(KIND);
